<script setup lang="ts">
import { ref, watch } from 'vue';
import WebScanner from './WebScanner.vue';
import { api } from '../api';
import { type Row, formatTime, localDateInput, fromLocalInput } from '../../shared/domain';
import { useCheckin } from '../../shared/checkin';
const props = defineProps<{ user: Row | null; target?: Row | null }>();const emit = defineEmits<{ (event: 'join'): void }>();
function locate(): Promise<Row> { return new Promise((resolve,reject) => { if (!navigator.geolocation || !window.isSecureContext) { reject(new Error('请使用HTTPS访问后定位，或联系现场组织者签到'));return; }navigator.geolocation.getCurrentPosition(p => resolve({ latitude: p.coords.latitude, longitude: p.coords.longitude, accuracy: p.coords.accuracy }),() => reject(new Error('无法获取位置，请检查定位授权后重试')), { enableHighAccuracy: true, timeout: 15000, maximumAge: 0 }); }); }
const { events,mine,signup,selected,settings,error,message,busy,staff,select,scanned,checkin } = useCheckin(() => props.user,api,locate);
const scan = ref(false), manage = ref(false), form = ref<Row>({}), saving = ref(false), qr = ref(''), expiresAt = ref('');
watch(settings, value => { qr.value = '';if (selected.value) form.value = { enabled: value.enabled, latitude: value.latitude ?? '', longitude: value.longitude ?? '', radius: value.radius || 200, opensAt: localDateInput(new Date(value.opensAt || selected.value.startsAt)), closesAt: localDateInput(new Date(value.closesAt || selected.value.endsAt)) }; });
watch(() => props.target, row => { if (row && props.user?.status === 'approved') select(row); }, { immediate: true });
async function useCurrent() { saving.value = true;try { const p = await locate();form.value.latitude = p.latitude;form.value.longitude = p.longitude; } catch(e) { error.value = (e as Error).message; } finally { saving.value = false; } }
async function save() { if (!selected.value) return;saving.value = true;error.value = '';try { await api('/events/' + selected.value.id + '/checkin-config','PUT',{ ...form.value, latitude: Number(form.value.latitude), longitude: Number(form.value.longitude), radius: Number(form.value.radius), opensAt: fromLocalInput(form.value.opensAt), closesAt: fromLocalInput(form.value.closesAt) });await select(selected.value);message.value = '签到设置已保存'; } catch(e) { error.value = (e as Error).message; } finally { saving.value = false; } }
async function generate() { if (!selected.value) return;saving.value = true;error.value = '';try { const data = await api('/events/' + selected.value.id + '/checkin-code','POST');const QRCode = await import('qrcode');qr.value = await QRCode.default.toDataURL(data.code,{ width: 280, margin: 2, errorCorrectionLevel: 'M' });expiresAt.value = data.expiresAt; } catch(e) { error.value = (e as Error).message; } finally { saving.value = false; } }
async function onScan(value: string) { if (await scanned(value)) { scan.value = false;manage.value = false; } }
</script>
<template><section><div class="checkin-heading"><p class="eyebrow">MEET HERE, CHECK IN HERE</p><h1>到场了，和老乡打个招呼。</h1><p>主动授权位置，完成已报名活动的现场签到。</p><div class="button-row"><button class="primary" @click="scan = !scan">{{ scan ? '收起扫一扫' : '扫一扫' }}</button><button v-if="staff" class="outline" @click="manage = !manage; selected = null">{{ manage ? '返回我的签到' : '设置活动签到点' }}</button></div></div><WebScanner v-if="scan" @result="onScan"/><p v-if="error" class="form-error" role="alert">{{ error }}</p><p v-if="message" class="status-note" role="status">{{ message }}</p><div v-if="user?.status !== 'approved'" class="empty"><h3>审核通过后即可签到</h3><button class="primary" @click="emit('join')">登录／查看入会状态</button></div><template v-else><div class="checkin-layout"><section class="panel"><h3>{{ manage ? '选择活动' : '我的活动' }}</h3><div v-if="!(manage ? events : mine).length" class="inline-empty">{{ manage ? '请先发布活动' : '还没有活动报名，报名后可在这里签到。' }}</div><button v-for="row in (manage ? events : mine)" :key="row.id" class="checkin-event" :class="{ selected: selected?.id === (manage ? row.id : row.eventId) }" @click="select(manage ? row : row.event)"><b>{{ manage ? row.title : row.event.title }}</b><small>{{ formatTime(manage ? row.startsAt : row.event.startsAt) }}</small><span v-if="!manage && row.status === 'checked_in'">已签到</span></button></section><section v-if="selected" class="panel"><h3>{{ selected.title }}</h3><p class="form-tip">{{ selected.location }}</p><form v-if="manage" @submit.prevent="save"><label class="checkbox"><input v-model="form.enabled" type="checkbox">开启地点签到</label><template v-if="form.enabled"><div class="form-grid"><label>签到点纬度（WGS84）<input v-model="form.latitude" type="number" step="any" min="-90" max="90" required></label><label>签到点经度（WGS84）<input v-model="form.longitude" type="number" step="any" min="-180" max="180" required></label></div><button type="button" class="outline small" :disabled="saving" @click="useCurrent">使用我当前所在的活动现场</button><label>允许半径（米）<input v-model="form.radius" type="number" min="50" max="2000" required></label><label>签到开始（北京时间）<input v-model="form.opensAt" type="datetime-local" required></label><label>签到结束（北京时间）<input v-model="form.closesAt" type="datetime-local" required></label><p class="form-tip">请在真实现场取点；签到窗口可设在活动开始前1小时至结束后2小时之间。</p></template><div class="button-row"><button class="primary" :disabled="saving">保存签到设置</button><button v-if="settings.enabled" type="button" class="outline" :disabled="saving" @click="generate">生成现场二维码</button></div><div v-if="qr" class="checkin-code"><img :src="qr" alt="活动签到二维码"><p>有效至 {{ formatTime(expiresAt) }}，重新生成后旧码失效。</p><p>扫码后仍须验证位置、时间及报名资格。</p></div></form><template v-else><p v-if="signup?.status === 'checked_in'" class="status-note">已签到 · {{ formatTime(signup.checkedAt) }}<br/>{{ signup.hoursFinalized === false ? '志愿时长等待组织者核定' : '已核定 ' + signup.hours + ' 小时' }}</p><template v-else-if="settings.enabled"><p class="prose">开放时间：{{ formatTime(settings.opensAt) }} — {{ formatTime(settings.closesAt) }}<br/>签到范围：距离活动签到点 {{ settings.radius }} 米以内。</p><p class="form-tip">点击后请求定位授权。只记录签到时间与距离，不保存你的原始坐标。</p><button class="primary full" :disabled="busy" @click="checkin">{{ busy ? '正在定位并核验…' : '授权定位并签到' }}</button></template><p v-else class="inline-empty">组织者尚未开放地点签到，请联系现场工作人员。</p></template></section></div></template></section></template>
<style scoped>.checkin-heading :is(h1,h2){font-size:28px;margin:14px 0}.checkin-heading>p:not(.eyebrow){font-size:13px;color:#8a9081;line-height:1.9}.checkin-heading .button-row{margin:25px 0}.checkin-layout{display:grid;grid-template-columns:300px minmax(0,1fr);gap:25px}.checkin-layout h3{font-size:20px;margin-bottom:18px}.checkin-event{display:block;width:100%;text-align:left;padding:18px;border-bottom:1px solid #e6dfd0;border-radius:12px}.checkin-event b{font-size:14px;display:block}.checkin-event small{display:block;color:#8b9489;font-size:12px;margin-top:10px}.checkin-event span{font-size:12px;color:#a3854e}.checkin-event.selected{background:#ede6d5}.checkin-code{text-align:center;background:#f1ecdf;padding:20px;border-radius:16px;margin-top:25px}.checkin-code img{width:240px;max-width:100%;border-radius:12px}.checkin-code p{font-size:12px;color:#8a7e67;line-height:1.8}.checkin-layout .prose{margin:20px 0}@media(max-width:900px){.checkin-layout{grid-template-columns:1fr}.checkin-heading :is(h1,h2){font-size:23px}}</style>
